update audit_ai_call_log
response = #{response}, prompt_tokens = #{promptTokens}, completion_tokens = #{completionTokens}, total_tokens = #{totalTokens}, status = #{status}, error_msg = #{errorMsg}, response_time = #{responseTime}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
