mapper.select:
select count(*) as total_count, sum(case when status = 1 then 1 else 0 end) as success_count, sum(case when status = 0 then 1 else 0 end) as fail_count, sum(case when status = 1 then 1 else 0 end) / count(*) * 100 as success_rate, sum(total_tokens) as total_tokens, sum(response_time) / count(*) as avg_response_time, sum(response_time) as total_response_time from audit_ai_call_log
AND user_id = #{userId}
AND scene = #{scene}
AND model = #{model}
AND date_format(call_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')
AND date_format(call_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')

select date_format(call_time, '%Y-%m-%d') as call_date, sum(prompt_tokens) as prompt_tokens, sum(completion_tokens) as completion_tokens, sum(total_tokens) as total_tokens, count(*) as call_count from audit_ai_call_log
AND user_id = #{userId}
AND scene = #{scene}
AND model = #{model}
and call_time >= date_sub(now(), interval 90 day)
group by date_format(call_time, '%Y-%m-%d') order by call_date desc
